# tests/test_calculator_core.py
import math
import pytest
from calculator_core import calculate

class TestAddition:
    def test_positive(self):   assert calculate(3.0, 2.0, 'Add') == (5.0, '+')
    def test_negative(self):   assert calculate(-1.0, -4.0, 'Add') == (-5.0, '+')
    def test_zeros(self):      assert calculate(0.0, 0.0, 'Add') == (0.0, '+')
    def test_float_precision(self):
        result, _ = calculate(0.1, 0.2, 'Add')
        assert math.isclose(result, 0.3, rel_tol=1e-9)

class TestDivision:
    def test_valid(self):      assert calculate(10.0, 2.0, 'Divide') == (5.0, '÷')
    def test_zero_divisor(self):
        with pytest.raises(ValueError, match='Division by zero'):
            calculate(5.0, 0.0, 'Divide')

class TestRouting:
    def test_unknown_op(self):
        with pytest.raises(ValueError, match='Unknown operation'):
            calculate(1.0, 1.0, 'Modulo')

