import math

OPERATIONS = {
    'Add': '+', 'Subtract': '-', 'Multiply': '×', 'Divide': '÷',
    'Power': '^', 'Modulo': '%', 'Square Root': '√',
}

# In calculate():
if operation == 'Power':       return num1 ** num2, symbol
if operation == 'Modulo':
    if num2 == 0: raise ValueError('Modulo by zero is not allowed.')
    return num1 % num2, symbol
if operation == 'Square Root':
    if num1 < 0:  raise ValueError('Square root of negative number is not defined.')
    return math.sqrt(num1), symbol

